(* [comment removed for export] *)
Definition block_ok (cnt : word) (bs : list byte) : Prop :=
  (1 <= Z.of_nat (length bs))%Z /\ (Z.of_nat (length bs) <= bv_unsigned cnt)%Z.

(* [comment removed for export] *)
Definition reads_ch (rch : word) (blocks : list (list byte)) : list event :=
  flat_map (fun bs => map (ReadEv rch) bs) blocks.

Lemma reads_ch_cons : forall rch bs blocks,
  reads_ch rch (bs :: blocks) = map (ReadEv rch) bs ++ reads_ch rch blocks.
Proof.
ltac2:(KReplay.run1 (kr_t_DrainSim ()) [] "h06blocksh12bsh23rchp;1p;4p;2p;3p-1R0p1008Ep4p710p9P0p1008hp4p710p9P0p1009TR1p4p710p9P0P1p4p7210p9P0P1p4p73110p9P0p100:2p4p710p9p100:jp4p70R0p1000kp4p710R1p8P0p100;Zp4p710R2p8P0p100<8p4p7210R3p8P0p10000p4p710R0p8p100<Up4p710R4P1p8P4P0p8p100=2p4p70R5g00=`R6p4p7210p8P5P1p8P5P4p8P5P2p8P5P3p8P5P0p8P5g000NR4p4p710p8P5p100><p4p7210p8p100>Yp4p7210R5P1p8P5P2p8P5P3p8P5P0p8p100?Ep4p70R5P1p8P5P2p8P5P3p8P5P0p8g001Gj10Tg001lj13Tg002Jj12Tg002mj11Tg00@;j18TP6j47Tg00A1j26TP4j34Tg006Dj25Tg007`#0#0#0R4#0#0#0#3#2%34#2R4#1R6%16g00AmR6#1P4P6f2R4#8f1C7f0,64546'5W0W1W2o"). Qed.

(* [comment removed for export] *)
Definition reads (blocks : list (list byte)) : list event :=
  reads_ch (Z_to_bv 64 0) blocks.

Lemma reads_cons : forall bs blocks,
  reads (bs :: blocks) = map (ReadEv (Z_to_bv 64 0)) bs ++ reads blocks.
Proof.
